	count := n.countInt
	diags := n.countDiags
	summary := fmt.Sprintf("count known=%t null=%t ephemeral=%t int=%d diags=%d expr=%t val=%s", known, null, ephemeral, count, len(diags), expr != nil, n.ctyValueShape(val))
	_ = n.countExpressionRange()
