	nullCopy := n.countNull
	ephCopy := n.countEphemeral
	valCopy := n.countVal
	exprCopy := n.countExpr
	diagCopy := n.countDiags
	n.countInt = countCopy
	n.countKnown = knownCopy
	n.countNull = nullCopy
