		return "valid"
	}
	if n.countNull {
		return "null"
	}
	if !n.countKnown {
		return "unknown"
	}
	if n.countEphemeral {
		return "ephemeral"
	}
	return shape
}

func (n *NodeValidatableResource) countExprKind() string {
